scwin.testDisplayFormatter = function(value) {
    console.log("displayFormatter");
    return value + " test!!";
}
scwin.testCustomFormatter = function(data, formattedData, rowIndex, colIndex) {
    console.log("customFormatter");
    return data + " test!!";
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. Property 탭 또는 Source 탭에서 grd1 의 senseReader 부분을 확인한다.
    //Check the senseReader portion of grd1 in the Property tab or Source tab.
    //Verify 1. senseReader="true"
    //Test step 2. col2 의 inputType 와 displayFormatter 부분을 확인한다.
    //Check col2's inputType and displayFormatter.
    //Verify 2. inputType="text" / displayFormatter="testDisplayFormatter"
    //Test step 3. col3 의 inputType 와 customFormatter 부분을 확인한다.
    //Check col3's inputType and customFormatter parts.
    //Verify 3. inputType="text" / customFormatter="testCustomFormatter"
    //Test step 4. 브라우저에서 확인한다.
    //Check in the browser.
    //Verify 4. 정상적으로 displayFormatter 와 customFormatter 이 적용된다. (그전버전에서는 customFormatter 가 동작하지 않음) 
    //displayFormatter and customFormatter are normally applied. (CustomFormatter does not work in earlier versions)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'wq_uuid_3_cell_0_2_text').value == '3333 test!!'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'wq_uuid_3_cell_1_2_text').value == '3333 test!!'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'wq_uuid_3_cell_2_2_text').value == '3333 test!!'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'wq_uuid_3_cell_3_2_text').value == '3333 test!!'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'wq_uuid_3_cell_4_2_text').value == '3333 test!!'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
